1	const priceList: Record<string, number> = {
2	  sword: 100,
3	  amulet: 60,
4	  staff: 80,
5	  potion: 40,
6	  rune: 25,
7	  moonstone: 25,
8	};
9	
10	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
11	
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_PRICE = 60;
14	
15	const COMPONENT_TYPES = ["rune", "moonstone"];
16	
17	const sumBy = (items: Item[], amount: (item: Item) => number): number =>
18	  items.reduce((sum, item) => sum + amount(item), 0);
19	
20	const sumOfItemPrices = (items: Item[]): number =>
21	  sumBy(items, (item) => priceList[item.type]);
22	
23	const countOf = (type: string, items: Item[]): number =>
24	  items.filter((item) => item.type === type).length;
25	
26	const componentPremium = (type: string, items: Item[]): number => {
27	  const count = countOf(type, items);
28	  return count === COMPONENT_BLOCK_SIZE
29	    ? COMPONENT_BLOCK_PRICE
30	    : count * priceList[type];
31	};
32	
33	export const basePremium = (items: Item[]): number => {
34	  const nonComponents = items.filter(
35	    (item) => !COMPONENT_TYPES.includes(item.type),
36	  );
37	  const componentsTotal = COMPONENT_TYPES.reduce(
38	    (total, type) => total + componentPremium(type, items),
39	    0,
40	  );
41	  return sumOfItemPrices(nonComponents) + componentsTotal;
42	};
43	
44	const PROCESSING_FEE = 5;
45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_RATE = 0.3;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	const FIRST_INSURANCE_RATE = 0.1;
49	const LOYALTY_DISCOUNT_RATE = 0.2;
50	const LOYALTY_THRESHOLD_YEARS = 2;
51	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
52	
53	type Customer = { yearsWithMHPCO: number };
54	
55	const curseSurchargeFor = (item: Item): number =>
56	  item.cursed ? basePremium([item]) * CURSE_SURCHARGE_RATE : 0;
57	
58	const enchantSurchargeFor = (item: Item): number =>
59	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
60	    ? basePremium([item]) * HIGH_ENCHANTMENT_RATE
61	    : 0;
62	
63	const surchargesFor = (item: Item): number =>
64	  curseSurchargeFor(item) + enchantSurchargeFor(item);
65	
66	// Premiums round in MHPCO's favor — up. (Claim payouts will round down, also in MHPCO's favor.)
67	const roundInFavorUp = (amount: number): number => Math.ceil(amount);
68	
69	const quotePremium = (
70	  items: Item[],
71	  customer: Customer,
72	  isFollowUp: boolean,
73	): number => {
74	  const policyBase = basePremium(items);
75	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_RATE;
76	  const loyaltyDiscount =
77	    customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
78	      ? policyBase * LOYALTY_DISCOUNT_RATE
79	      : 0;
80	  const followUpDiscount = isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0;
81	  const policyCharges =
82	    policyBase + firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
83	
84	  const itemSurcharges = sumBy(items, surchargesFor);
85	
86	  return roundInFavorUp(policyCharges + itemSurcharges + PROCESSING_FEE);
87	};
