89	const insuranceValueList: Record<string, number> = {
90	  sword: 1000,
91	  amulet: 600,
92	  staff: 800,
93	  potion: 400,
94	  rune: 250,
95	  moonstone: 250,
96	};
97	
98	const CAP_MULTIPLIER = 2;
99	const DEDUCTIBLE = 100;
100	
101	const insuranceSum = (items: Item[]): number =>
102	  sumBy(items, (item) => insuranceValueList[item.type]);
103	
104	type Damage = { itemType: string; amount: number };
105	type Incident = { cause: string; damages: Damage[] };
106	
107	type QuoteStep = { op: "quote"; items: Item[] };
108	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
109	type Step = QuoteStep | ClaimStep;
110	type Scenario = { customer: Customer; steps: Step[] };
111	
112	type Policy = { items: Item[]; remainingCap: number };
113	type QuoteResult = { premium: number };
114	type ClaimResult = { payout: number; remainingCap: number };
115	type StepResult = QuoteResult | ClaimResult;
116	
117	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
118	  const policies: Record<number, Policy> = {};
119	  let quoteCount = 0;
120	
121	  const handleQuote = (step: QuoteStep, index: number): QuoteResult => {
122	    const isFollowUp = quoteCount > 0;
123	    quoteCount += 1;
124	    policies[index] = {
125	      items: step.items,
126	      remainingCap: insuranceSum(step.items) * CAP_MULTIPLIER,
127	    };
128	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
129	  };
130	
131	  const handleClaim = (step: ClaimStep): ClaimResult => {
132	    const policy = policies[step.policy];
133	    const payout = sumBy(
134	      step.incident.damages,
135	      (damage) => damage.amount - DEDUCTIBLE,
136	    );
137	    policy.remainingCap -= payout;
138	    return { payout, remainingCap: policy.remainingCap };
139	  };
140	
141	  const results = scenario.steps.map((step, index): StepResult =>
142	    step.op === "quote" ? handleQuote(step, index) : handleClaim(step),
143	  );
144	
145	  return { results };
146	};
